namespace skycued {

namespace {

std::string baseName(const std::string& path)
{
    const size_t slash = path.rfind('/');
    return slash == std::string::npos ? path : path.substr(slash + 1);
}

std::string stringArray(const std::vector<std::string>& values)
{
    std::vector<std::string> quoted;
    for (const auto& v : values) {
        std::string s;
        appendJsonString(s, v);
        quoted.push_back(std::move(s));
    }
    return jsonArray(quoted);
}

// The built-in default of `key`; "" for a key with none (receiver.lat/lon).
std::string defaultText(const std::string& key)
{
    static const Config defaults;
    const std::string text = configValueText(defaults, key);
    return text.find("nan") != std::string::npos ? std::string() : text;
}

const char* schemaType(const KeySpec& spec)
{
    const std::string key = spec.key;
    if (key == "cues.tcp_connect" || key == "cues.udp_targets")
        return "host_port_list";
    for (const char* path : {"inputs.file", "filters.allow_list_file", "filters.block_list_file", "recording.dir",
                             "paths.state_dir", "paths.map_dir", "paths.locations_file", "stats.file"})
        if (key == path)
            return "path";
    switch (spec.type) {
    case KeyType::integer: return "int";
    case KeyType::number: return "float";
    case KeyType::boolean: return "bool";
    case KeyType::strings: return spec.values.empty() ? "string" : "string_set";
    case KeyType::string: break;
    }
    return spec.values.empty() ? "string" : "enum";
}

// Drops a trailing numeric range remark (", -90..90", "; > 0", "; >= 0.1")
// or a leading one ("100..100000; ").
std::string stripRange(const std::string& doc)
{
    static const std::regex remark(R"(\s*[,;]\s*(-?[0-9.]+\.\.-?[0-9.]+|[<>]=?\s*-?[0-9.]+)\s*$)");
    static const std::regex lead(R"(^-?[0-9.]+\.\.-?[0-9.]+\s*;\s*)");
    return std::regex_replace(std::regex_replace(doc, remark, ""), lead, "");
}

}  // namespace

std::string configSchemaJson()
{
    static const std::string cached = [] {
    const auto comments = exampleComments(kExampleToml);
    std::vector<std::string> keys;
    for (const auto& spec : keySpecs()) {
        const bool has_min = std::isfinite(spec.lo), has_max = std::isfinite(spec.hi);
        std::string doc;
        const auto it = comments.find(spec.key);
        if (it != comments.end())
            doc = has_min || has_max ? stripRange(it->second) : it->second;
        JsonWriter entry;
        entry.add("key", spec.key)
            .add("type", schemaType(spec))
            .add("class", keyClassName(spec.cls))
            .add("default", defaultText(spec.key))
            .add("doc", doc);
        if (has_min)
            entry.add("min", spec.lo);
        if (has_max)
            entry.add("max", spec.hi);
        if (!spec.values.empty())
            entry.addRaw("values", stringArray(spec.values));
        if (relativeOnlyKey(spec.key))
            entry.add("relative_only", true);
        keys.push_back(entry.str());
    }
    return JsonWriter().addRaw("keys", jsonArray(keys)).str();
    }();
    return cached;
}

std::string pendingRestartJson(const RuntimeConfig& runtime)
{
    std::vector<std::string> pending;
    for (const auto& key : runtime.pendingRestartKeys())
        pending.push_back(JsonWriter()
                              .add("key", key)
                              .add("running", configValueText(runtime.running(), key))
                              .add("configured", configValueText(runtime.configured(), key))
                              .str());
    return jsonArray(pending);
}

std::string configJson(const DaemonInfo& info, const RuntimeConfig& runtime, const LocationFacts& locations,
                       std::chrono::system_clock::time_point now)
{
    const Config effective = runtime.effective();
    const Overlay overlay = runtime.overlay();

    std::vector<std::string> files;  // JSON objects
    for (const auto& r : info.recorders) {
        if (!r.second)
            continue;
        for (const char* ext : {"jsonl", "csv"}) {
            const std::string path = r.second->currentPath(ext);
            if (!path.empty())
                files.push_back(JsonWriter()
                                    .add("name", baseName(path))
                                    .add("stream", r.first)
                                    .add("bytes", static_cast<int64_t>(r.second->bytesWritten(ext)))
                                    .str());
        }
    }
    const auto uptime = std::chrono::duration_cast<std::chrono::seconds>(now - info.started).count();
    JsonWriter daemon;
    daemon
                                   .add("version", info.version)
                                   .add("started", formatIso8601Ms(info.started))
                                   .add("uptime_s", static_cast<int64_t>(std::max<decltype(uptime)>(0, uptime)))
                                   .add("config_path", info.config_path)
                                   .add("inputs_path", info.inputs_path)
                                   .add("overlay_path", runtime.overlayPath())
                                   .add("overlay_active", !overlay.empty())
                                   .add("overrides_path", runtime.overridesPath())
                                   .add("www_dir", info.www_dir)
                                   .add("map_dir", info.map_dir)
                                   .add("record_dir", effective.record_dir)
                                   .addRaw("recording_files", jsonArray(files))
                                   .add("log_level", info.log_level)
                                   .add("mode", info.replay_file.empty() ? "live" : "replay");
    if (!info.replay_file.empty())
        daemon.addRaw("replay", JsonWriter()
                                    .add("file", info.replay_file)
                                    .add("speed", info.replay_speed)
                                    .add("loop", info.replay_loop)
                                    .str());
    daemon.add("readsb", info.readsb).add("dump978", info.dump978);
    daemon.add("allow_restart", effective.web_allow_restart).add("supervisor", info.supervisor);
    daemon.addRaw("locations", JsonWriter()
                                   .add("learned_path", locations.learned_path)
                                   .add("learned", static_cast<int64_t>(locations.learned))
                                   .add("operator_path", locations.operator_path)
                                   .add("operator", static_cast<int64_t>(locations.operator_rows))
                                   .add("operator_rejected", static_cast<int64_t>(locations.operator_rejected))
                                   .add("operator_overflow", static_cast<int64_t>(locations.operator_overflow))
                                   .str());

    const auto& restart = restartConfigKeys();
    std::map<std::string, std::string> layer;  // key -> "env" or "--set"
    for (const auto& src : effective.sources)
        if (src.source == "env" || src.source == "--set")
            layer[src.key] = src.source == "env" ? "env" : "set";
    std::vector<std::string> keys;
    for (const auto& key : knownConfigKeys()) {
        const bool from_overlay = layer.find(key) == layer.end() &&
                                  ((key == "filters.max_range_nm" && overlay.max_range_nm.has_value()) ||
                                   (key == "filters.min_elevation_deg" && overlay.min_elevation_deg.has_value()));
        const auto flag = info.cli_overrides.find(key);
        const auto pinned = layer.find(key);
        const KeyClass cls = keyClassOf(key);
        std::string value, source, running;
        if (from_overlay) {
            value = configValueText(effective, key);
            source = "runtime";
        } else if (flag != info.cli_overrides.end()) {
            value = flag->second;  // RuntimeConfig parsed the files alone
            source = "flag";
        } else if (pinned != layer.end()) {
            value = configValueText(effective, key);
            source = pinned->second;
        } else {
            value = configValueText(effective, key);
            source = effective.override_keys.count(key) ? "overrides"
                     : effective.file_keys.count(key)   ? "conf"
                                                        : "default";
            // The panel edits the files: a key that waits for a restart shows
            // what the files say now, and what runs when that differs.
            if (cls != KeyClass::live) {
                value = configValueText(runtime.configured(), key);
                const std::string run = configValueText(runtime.running(), key);
                if (run != value)
                    running = run;
            }
        }
        const bool editable = cls != KeyClass::bootstrap && source != "env" && source != "set" && source != "flag";
        JsonWriter entry;
        entry.add("key", key)
            .add("value", value)
            .add("source", source)
            .add("restart", std::find(restart.begin(), restart.end(), key) != restart.end())
            .add("class", keyClassName(cls))
            .add("editable", editable);
        if (!running.empty())
            entry.add("running", running);
        const auto file = runtime.configured().file_values.find(key);
        if (file != runtime.configured().file_values.end())
            entry.add("file_value", file->second);
        entry.add("default", defaultText(key));
        keys.push_back(entry.str());
    }
    return JsonWriter()
        .addRaw("daemon", daemon.str())
        .addRaw("keys", jsonArray(keys))
        .addRaw("pending_restart", pendingRestartJson(runtime))
        .str();
}

}  // namespace skycued
